<div class="topbar"><h1>Accounts Dashboard</h1><a class="btn btn-ghost" href="<?=url('/admin/invoices')?>">Invoices</a></div><div class="tiles"><?php foreach($byCurrency as $x):?><div class="tile"><b><?=e($x['currency'])?></b><div>Invoiced <?=e(Money::format((int)$x['invoiced_minor'],$x['currency']))?></div><div>Paid <?=e(Money::format((int)$x['paid_minor'],$x['currency']))?></div><strong>Outstanding <?=e(Money::format((int)$x['outstanding_minor'],$x['currency']))?></strong></div><?php endforeach;?></div><div class="card"><h3>Recent payments</h3><table><tr><th>Payment</th><th>Invoice</th><th>Amount</th><th>Date</th></tr><?php foreach($recentPayments as $p):?><tr><td><?=e($p['payment_no'])?></td><td><?=e($p['doc_no'])?></td><td><?=e(Money::format((int)$p['amount_minor'],$p['currency']))?></td><td><?=e($p['paid_on'])?></td></tr><?php endforeach;?></table></div>
